begin;
select set_config('request.jwt.claim.sub','2d50291d-03e3-46a3-b3d8-c4550bc1bce7',true);
do $test$
declare prefix text:='TEST-AKAD-'||substr(gen_random_uuid()::text,1,8);typ text;lot text;bank text;notary text;sale uuid;kpr uuid;cash uuid;data jsonb;total numeric;failed boolean;today date:=(now() at time zone 'Asia/Jakarta')::date;
begin
 select id_tipe into typ from public.master_tipe_rumah where status_aktif limit 1;
 select id_bank into bank from public.master_bank where status_aktif and is_kpr limit 1;
 select id_notaris into notary from public.master_notaris where status_aktif limit 1;
 if typ is null or bank is null or notary is null then raise exception 'Test needs active type, bank and notary';end if;
 insert into public.master_kavling(id_kavling,blok,no_kavling,id_tipe,status_kavling,harga_standar) values(prefix||'1',prefix,'1',typ,'AVAILABLE',100000000),(prefix||'2',prefix,'2',typ,'AVAILABLE',100000000),(prefix||'3',prefix,'3',typ,'AVAILABLE',100000000);
 execute 'set local role authenticated';
 sale:=public.save_sales_v2_atomic(jsonb_build_object('id_kavling',prefix||'1','nama_konsumen',prefix,'status_sales','BOOKING','jenis_pembayaran','CASH_BERTAHAP','tgl_booking',today,'tenor_bulan',6,'pola_pelunasan','CICILAN_FLEKSIBEL'));
 failed:=false;begin perform public.record_sales_akad_atomic(sale,today,notary);exception when others then if sqlerrm like '%MENUNGGU PELUNASAN%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Cash Bertahap akad before full payment';end if;
 select total_harga_jual into total from public.v_sales_financial_position where id_sales=sale;
 data:=jsonb_build_object('id_sales',sale,'tanggal_penerimaan',today,'metode_penerimaan','TRANSFER','id_bank_penerimaan',bank);
 perform public.post_sales_receipt_v2_atomic(data||jsonb_build_object('jenis_penerimaan','BOOKING_FEE','nominal',1000000));
 perform public.post_sales_receipt_v2_atomic(data||jsonb_build_object('jenis_penerimaan','UANG_MUKA','nominal',total-2000000));
 failed:=false;begin perform public.record_sales_akad_atomic(sale,today,notary);exception when others then if sqlerrm like '%MENUNGGU PELUNASAN%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Partial Cash Bertahap akad';end if;
 perform public.post_sales_receipt_v2_atomic(data||jsonb_build_object('jenis_penerimaan','CICILAN_CASH_BERTAHAP','nominal',1000000));
 perform public.record_sales_akad_atomic(sale,today,notary);
 if not exists(select 1 from public.sales where id_sales=sale and status_sales='AKAD' and status_aktif and tgl_akad=today and id_notaris=notary and target_akad is null) then raise exception 'Actual akad fields/status/target mismatch';end if;
 if public.record_sales_akad_atomic(sale,today,notary)<>sale then raise exception 'Identical akad retry failed';end if;
 cash:=public.save_sales_v2_atomic(jsonb_build_object('id_kavling',prefix||'3','nama_konsumen',prefix,'status_sales','BOOKING','jenis_pembayaran','CASH','tgl_booking',today));
 select total_harga_jual into total from public.v_sales_financial_position where id_sales=cash;
 data:=data||jsonb_build_object('id_sales',cash);
 perform public.post_sales_receipt_v2_atomic(data||jsonb_build_object('jenis_penerimaan','BOOKING_FEE','nominal',1000000));
 perform public.post_sales_receipt_v2_atomic(data||jsonb_build_object('jenis_penerimaan','UANG_MUKA','nominal',total-1000000));
 perform public.record_sales_akad_atomic(cash,today,notary);
 kpr:=public.save_sales_v2_atomic(jsonb_build_object('id_kavling',prefix||'2','nama_konsumen',prefix,'status_sales','BOOKING','jenis_pembayaran','KPR','id_bank',bank,'tgl_booking',today));
 failed:=false;begin perform public.record_sales_akad_atomic(kpr,today,notary);exception when others then if sqlerrm like '%BOOKING FEE DAN UANG MUKA%' then failed:=true;else raise;end if;end;if not failed then raise exception 'KPR without prerequisites';end if;
 data:=data||jsonb_build_object('id_sales',kpr);
 perform public.post_sales_receipt_v2_atomic(data||jsonb_build_object('jenis_penerimaan','BOOKING_FEE','nominal',1000000));
 perform public.post_sales_receipt_v2_atomic(data||jsonb_build_object('jenis_penerimaan','UANG_MUKA','nominal',1000000));
 failed:=false;begin perform public.record_sales_akad_atomic(kpr,today+1,notary);exception when others then if sqlerrm like '%MASA DEPAN%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Future actual akad';end if;
 failed:=false;begin perform public.record_sales_akad_atomic(kpr,today,'NOT-EXISTS');exception when others then if sqlerrm like '%NOTARIS AKTIF%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Invalid notary';end if;
 perform public.record_sales_akad_atomic(kpr,today,notary);
 perform public.post_sales_receipt_v2_atomic(data||jsonb_build_object('jenis_penerimaan','PENCAIRAN_KPR','nominal',1000000));
 if not exists(select 1 from public.sales where id_sales=kpr and status_sales='AKAD' and status_aktif) then raise exception 'KPR deactivated before disbursement';end if;
 if has_function_privilege('anon','public.record_sales_akad_atomic(uuid,date,text)','execute') then raise exception 'Anonymous akad';end if;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000000',true);
 failed:=false;begin perform public.record_sales_akad_atomic(kpr,today,notary);exception when others then if sqlerrm like '%FORBIDDEN%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Unauthorized akad';end if;
 execute 'reset role';
end $test$;
rollback;
select 'PASS: Cash/Cash Bertahap paid gate, KPR prerequisites and post-akad disbursement, actual date/notary, optional planned date, idempotent retry, active lifecycle, permissions' verification;
